    this.queryPolicy = {
      hashMark: '#',
      queryDelimiter: '?',
      pairDelimiter: '&',
      encodeReplacements: [
        [/%3A/gi, ':'],
        [/%24/g, '$'],
        [/%2C/gi, ','],
        [/%20/g, '+'],
        [/%5B/gi, '['],
