      cookieSplitPatternPrefix: '(^|;\\s*)(',
      cookieSplitPatternSuffix: ')=([^;]*)',
      basicPrefix: 'Basic ',
      proxyAuthPrefix: 'Basic ',
      acceptEncoding: 'gzip, compress, deflate',
      brotliToken: ', br'
    };

    this.configPolicy = {
      emptyConfig: {},
      defaultCaseless: undefined,
      defaultMethod: 'get',
      allowUnknownOptions: false,
      version: VERSION,
      mergeStyle: 'config',
      proxyAuthSeparator: ':',
      addressFamilyDot: '.',
      ipv4: 4,
      ipv6: 6,
      deprecatedWarnings: {}
